// game day: the season's day counter (+ the season), so the suit and co-host change
// every game day and stay put while you browse the hub
function deskDay(save) {
  const se = save.season; if (!se) return 0;
  return (se.num || 1) * 1000 + ((se.dayNo || 0) % 1000);
}
// the suit of the day: a fresh shuffle each season, read in order, so no set repeats two days running
function deskSuit(save) {
  if (typeof DBG !== 'undefined' && DBG.on && DBG.deskSuit != null && SUITS[DBG.deskSuit]) { const s0 = SUITS[DBG.deskSuit]; return { name: s0[0], coat: s0[1], acc: s0[2], pat: s0[3], tie: s0[4], tieAcc: s0[5], tiePat: s0[6] }; }
  const day = deskDay(save), season = Math.floor(day / 1000), i = day % 1000;
  const order = SUITS.map((_, k) => k), r = mulberry32(season * 7919 + 13);
  for (let k = order.length - 1; k > 0; k--) { const j = Math.floor(r() * (k + 1)); [order[k], order[j]] = [order[j], order[k]]; }
  const s = SUITS[order[i % order.length]];
  return { name: s[0], coat: s[1], acc: s[2], pat: s[3], tie: s[4], tieAcc: s[5], tiePat: s[6] };
}
// who sits beside Bone today: T works every other one of your games, and every tournament final (and the league final)
// no matter what; the rest rotate through the other co-hosts. Settled once per game day, so it can't change mid-broadcast.
function deskCohost(save) {
  if (typeof DBG !== 'undefined' && DBG.on && DBG.deskHost) { const f = COHOSTS.find(c => c.id === DBG.deskHost); if (f) return f; }
  const se = save && save.season, day = deskDay(save), T0 = COHOSTS[0], rest = COHOSTS.slice(1);
  if (!se) return T0;
  if (se.deskHost && se.deskHost.day === day) return COHOSTS.find(c => c.id === se.deskHost.id) || T0;
  let host;
  try {
    const cur = typeof currentDay === 'function' ? currentDay(save) : null, g = cur && cur.userGid ? se.games[cur.userGid] : null;
    const fin = g && typeof gameStage === 'function' && gameStage(save, g).final;
    const n = Object.values(se.games).filter(x => x.played && (x.home === save.userTeamId || x.away === save.userTeamId)).length;   // your games so far
    if (fin || n % 2 === 0) host = T0;
    else host = rest[(Math.floor(n / 2) + (se.num || 1) * 2) % rest.length];
  } catch (e) { host = COHOSTS[day % COHOSTS.length]; }
  if (deskDay(save) === day) se.deskHost = { day, id: host.id };
  return host;
}

// ---------- patterns: the colour of one pixel of a patterned cloth
const cellHash = (x, y) => { let h = (x * 374761393 + y * 668265263) | 0; h = (h ^ (h >>> 13)) * 1274126177; return ((h ^ (h >>> 16)) >>> 0) / 4294967296; };
function patPx(pat, x, y, base, acc, t = 0) {
  switch (pat) {
    case 'plaid': { const a = (x % 7) < 2, b = (y % 7) < 2; return a && b ? shade(acc, -0.15) : a || b ? acc : (x + y) % 7 === 3 ? shade(base, 0.12) : base; }
    case 'polka': return ((x + (Math.floor(y / 4) % 2) * 2) % 4 === 1 && y % 4 === 1) ? acc : base;
    case 'stripe': return x % 4 === 0 ? acc : base;
    case 'check': return ((x >> 1) + (y >> 1)) % 2 ? acc : base;
    case 'hounds': { const u = x % 4, v = y % 4; return (u + v === 3 || (u < 2 && v < 2 && u !== v)) ? acc : base; }
    case 'argyle': { const u = Math.abs((x % 8) - 4), v = Math.abs((y % 8) - 4); return u + v < 3 ? acc : (x + y) % 8 === 0 ? shade(acc, 0.3) : base; }
    case 'paisley': { const cx = Math.floor(x / 5), cy = Math.floor(y / 5), u = x % 5, v = y % 5; if (cellHash(cx, cy) < 0.5) return base;
      return (u === 2 && v >= 1 && v <= 3) || (v === 2 && u === 1) || (u === 3 && v === 1) ? acc : base; }
    case 'floral': { const cx = Math.floor(x / 6), cy = Math.floor(y / 6), u = x % 6, v = y % 6; if (cellHash(cx, cy) < 0.35) return base;
      if (u === 2 && v === 2) return '#ffd23f'; return (Math.abs(u - 2) + Math.abs(v - 2) === 1) ? acc : base; }
    case 'leopard': { const cx = Math.floor(x / 4), cy = Math.floor(y / 4), u = x % 4, v = y % 4; if (cellHash(cx, cy) < 0.45) return base;
      return (u === 0 || v === 0) ? acc : (u === 1 && v === 1) ? shade(base, -0.2) : base; }
    case 'sequin': { const s = cellHash(x, y + 1000); return s > 0.9 ? acc : s > 0.82 && ((t >> 2) + x) % 3 === 0 ? '#ffffff' : (x + y) % 2 ? shade(base, -0.08) : base; }
    case 'dots': return (x % 3 === 1 && y % 3 === 1) ? acc : base;
    default: return base;
  }
}

